// High quality botanical leaf dummy photos generated in software
export interface SoftwareVisionFrame {
  prediction: 'Healthy' | 'Powdery' | 'Rust';
  healthy: number;
  powdery: number;
  rust: number;
  imageUrl: string;
}

export const DUMMY_FRAMES: SoftwareVisionFrame[] = [
  {
    prediction: 'Healthy',
    healthy: 92.5,
    powdery: 4.3,
    rust: 3.2,
    imageUrl: 'data:image/jpeg;base64,',
  },
  {
    prediction: 'Powdery',
    healthy: 12.8,
    powdery: 81.6,
    rust: 5.6,
    imageUrl: 'data:image/jpeg;base64,',
  },
  {
    prediction: 'Rust',
    healthy: 8.5,
    powdery: 14.1,
    rust: 77.4,
    imageUrl: 'data:image/jpeg;base64,',
  },
];

let currentIndex = 0;

export function getNextSoftwareVisionFrame(): SoftwareVisionFrame {
  const frame = DUMMY_FRAMES[currentIndex % DUMMY_FRAMES.length];
  currentIndex++;
  return frame;
}

export function getDefaultSoftwareVisionFrame(): SoftwareVisionFrame {
  return DUMMY_FRAMES[0];
}
